# November 19, 2026: Washington County, Vermont (region vtc, Central Vermont), first pass.
# Drawn at random by tools/choose.py. Barre's granite country, the Northfield covered bridges, the old meeting houses of
# East Montpelier and Calais, the Mad River Valley bridges, and the 1944 bomber wreck on Camel's Hump.
# Facts come from Wikipedia articles read through tools/wiki_raw.py (each summarising its National Register form),
# HMdb marker texts, and the managing bodies' own pages read through tools/page.py, as linked on each place.
from data_b import N
from data_ma import W
BATCH={'key':'vtc_kaqi','label':'Washington County, Vermont','added':'2026-11-19 02:57'}
def HM(n,t): return ['HMdb: '+t,'https://www.hmdb.org/m.asp?m=%d'%n]
MTA=['Millstone Trails Association: FAQ','https://www.millstonetrails.org/faq/']
PLACES=[
# ---- Barre: granite ----
N('millstone-hill-quarries','Millstone Hill old granite quarries','Barre Town','vtc','industry','ruins',44.15304,-72.46779,'area','public','walk','','1800s–',
  'Millstone Hill above Websterville and East Barre was quarried for granite by as many as 75 independent operators; today Rock of Ages is the only one still working there and owns much of the land. The Barre and Chelsea railroad reached East Barre in 1893 to carry the stone, and the village boomed. The worked-out quarry land is now crossed by about 30 miles of trails over some 1,500 acres.',
  'Water-filled quarry pits, big piles of granite waste (grout) and old quarry roads along the trails; the aerial shows dozens of flooded pits in the woods south of Brook Street.',
  'A whole hillside of abandoned granite quarries you can walk among.',
  'The trails are kept by the volunteer Millstone Trails Association on Barre Town Forest land and on land owned by Rock of Ages, which allows the use. Walking and hiking are free; mountain biking needs a $10 day pass or membership. Park at the Town Forest lots at 44 Brook Street or the end of Barclay Quarry Road, open to anyone using the trails. Dogs under control are welcome. Swimming and cliff-jumping in the quarries are prohibited: it is trespassing on Rock of Ages land and dangerous. No camping or fires. Hours not checked.',
  [MTA,['Millstone Trails Association: passes','https://www.millstonetrails.org/passes/'],['Millstone Trails Association: about the area','https://www.millstonetrails.org/about-mta/about-the-area/'],['Trail Finder: Millstone Trails','https://trailfinder.info/trails/trail/millstone-trails'],HM(156424,'Historic Millstone Hill')],
  th=[44.15693,-72.46887],thn='Barre Town Forest lot, 44 Brook Street',brick='no'),
N('vermont-granite-museum','Jones Brothers Granite Shed (Vermont Granite Museum)','Barre','vtc','industry','standing',44.21184,-72.52103,'exact','public','drive','now','1895–1975',
  'Jones Brothers, founded in 1882, built this shed in 1895, an early "straight shed" of the kind that replaced the older horseshoe-shaped ones. Big blocks of granite were cut here into finished work, mostly cemetery memorials. The firm was the oldest working granite company in Vermont when it stopped in 1975; the shed, the main survivor of a larger complex, became a museum in 1997.',
  'The long shed itself, now the Vermont Granite Museum, with exhibits on quarrying and stone carving and walking trails on the grounds. The Barre and Chelsea locomotive No. 14 is on the site (HMdb marker). Open to the public in season.',
  '',
  'Vermont Granite Museum, 7 Jones Brothers Way off US 302. Its page gives Tuesday to Saturday, 10 a.m. to 4 p.m., in the museum season (May 1 to October 31); admission charged (seniors and veterans $12; children 4 and under free). Accessible parking by the entrance.',
  [W('Vermont Granite Museum'),['Vermont Granite Museum: visit','https://www.vtgranitemuseum.org/?p=80'],HM(261351,'Jones Brothers Granite Shed'),HM(281180,'Barre & Chelsea #14')],brick='no'),
N('hope-cemetery-barre','Hope Cemetery','Barre','vtc','burial','standing',44.21117,-72.49975,'site','public','drive','cemeteries','1895–',
  'Barre bought 53 acres of farmland for the cemetery in 1895, laid out by Edward P. Adams, just as stone carvers from Italy and elsewhere were arriving for the granite boom. Silicosis from granite dust and the 1918-19 flu killed many of them, and many carvers designed their own stones: one estimate is that three quarters of the memorials were designed by the people under them. It has grown to 65 acres and more than 10,000 memorials.',
  'Carved granite memorials of every shape, many of them portraits and sculpture by Barre\'s own carvers. The HMdb lists a 1918 Spanish flu memorial and a veterans memorial here.',
  'An outdoor sculpture gallery made by the carvers for themselves.',
  'A city cemetery run by the City of Barre, which has a cemetery committee (its minutes are on barrecity.org). On Maple Avenue (VT 14) north of downtown. Hours not checked; respect burials and services.',
  [W('Hope Cemetery'),HM(281172,'1918 Spanish Flu Memorial'),['City of Barre: cemetery committee minutes (2025)','https://www.barrecity.org/client_media/files/minutes/FY25/Cemetery%20Minutes%20%205-12-25.pdf']],brick='?'),
N('old-labor-hall-barre','Socialist Labor Party Hall (Old Labor Hall)','Barre','vtc','civic','standing',44.198925,-72.506989,'exact','view','drive','','1900',
  'Volunteers from Barre\'s Italian community built this hall in 1900 for the Socialist Labor Party, the only building known to have been built by its members. It held union offices, including the granite cutters\' union from 1900 to 1936, along with dances and political meetings; in 1903 an argument between socialists and anarchists here ended in the shooting of the stone carver Elia Corti, and in 1912 children of the Lawrence strikers were received here. It became a fruit warehouse in 1936; the Barre Historical Society bought and restored it from 1995. A National Historic Landmark since 2000.',
  'A two-storey brick hall on a granite foundation, with a carved granite medallion over the door showing an arm holding a hammer and the letters SLP. Inside, the front room keeps its maple floor, pressed-tin ceiling and beadboard (the 1990s survey). The public sees the inside at events held there.',
  'Where anarchists and socialists argued Barre\'s future, built by the people who argued.',
  'Owned by the Barre Historical Society, 46 Granite Street. Used for public events, concerts, lectures and rentals (VTDigger, 2012); no regular opening hours found. See it from the street at other times.',
  [W('Socialist Labor Party Hall'),HM(261346,'Socialist Labor Party Hall'),['UVM historic preservation survey: interior','https://www.uvm.edu/~histpres/HPJ/NR/barrelabor/interior.html'],['VTDigger: the Old Labor Hall\'s third life (2012)','https://vtdigger.org/2012/02/05/in-this-state-how-the-old-socialist-labor-party-hall-got-its-third-life/']],brick='?'),
N('joshua-twing-gristmill','Joshua Twing Gristmill','Barre','vtc','industry','standing',44.2051,-72.5113,'exact','view','drive','','1844',
  'Joshua Twing bought this mill site on the Stevens Branch in 1807 and over the decades built mills and a foundry (1818) here, making iron parts for mills, water wheels among them. This 1844 gristmill is the only building of his left; most of the complex came down in the 1960s.',
  'A 2 3/4-storey brick mill in Greek Revival dress, with an unusual stair tower in front whose open ground floor let a wagon drive under it, and a big granite-framed door on the second floor whose stairs are gone. The Register form describes a double spiral staircase and marbled columns inside; interior not checked.',
  '',
  'Privately owned, at 450 North Main Street (US 302). See it from the street.',
  [W('Joshua Twing Gristmill')],brick='yes'),
N('barre-opera-house','Barre City Hall and Opera House','Barre','vtc','civic','standing',44.19680,-72.50166,'exact','public','drive','','1899',
  'Built in 1899 to the design of George G. Adams after the earlier city hall and opera house burned in 1898. The city offices are on the lower floors and the opera house above has served most of the time since as a theatre.',
  'A four-storey yellow brick and granite Beaux Arts front with a three-storey recessed arch, ironwork round the door and a wrought-iron balcony across the arch. Inside the theatre only at performances; interior not checked.',
  '',
  'City of Barre, 6 North Main Street. City offices keep weekday hours; the Barre Opera House stages performances through the year. Hours not checked.',
  [W('Barre Opera House'),HM(280926,'Barre City Hall and Opera House')],brick='no'),
# ---- Montpelier and East Montpelier ----
N('montpelier-railroad-turntable','Railroad turntable, Turntable Park','Montpelier','vtc','rail','standing',44.25458,-72.57318,'exact','public','walk','stations','1907',
  'A gallows turntable built in 1907 to swing steam locomotives round and line them up with the tracks into a neighbouring engine house, part of the rail yards that served Montpelier\'s granite trade along the river. An electric motor turned it on a central pivot.',
  'The turntable itself: a riveted truss track deck on a concrete pedestal, sitting in its circular concrete pit, with a marker beside it.',
  '',
  'Turntable Park (so named on the HMdb marker), a riverfront park on Stone Cutters Way; owner not checked, assumed open to the public as a park. Street and lot parking nearby; the Stone Cutters Way lot is mapped about 100 m south. Hours not checked.',
  [HM(188108,'Railroad Turntable, circa 1907')],th=[44.25383,-72.57225],thn='Stone Cutters Way lot',brick='no'),
N('union-meetinghouse-east-montpelier','Old Meeting House (Union Meetinghouse)','East Montpelier','vtc','worship','standing',44.28345,-72.52666,'site','view','drive','','1822–1825',
  'Montpelier\'s first Methodists leased this site in 1822 from Parley Davis, who had set the land aside as a town common, and Lovel Kelton of Calais raised the frame. Montpelier held its town meetings here until 1848-49, and East Montpelier until 1890. The building was shared by several congregations; regular worship came back in the 1960s with a non-denominational society. The marker says the building was completed in 1825; Wikipedia, from the Register form, gives 1823–26.',
  'A clapboarded Federal meeting house with a projecting entry, a fan in its pediment and a tower of a square stage and two octagonal ones under a bell-cast roof and spire. Interior not checked.',
  'The oldest church building round Montpelier.',
  'On Center Road west of Brazier Road (1620 Center Road). Used by a non-denominational congregation; see it from the road at other times. Hours not checked.',
  [W('Union Meetinghouse (East Montpelier, Vermont)'),HM(272140,'The Old Meeting House')],conf='mixed',brick='no'),
N('east-village-meetinghouse','Old Brick Church (East Village Meetinghouse)','East Montpelier','vtc','worship','standing',44.27192,-72.48667,'site','public','drive','','1833–1834',
  'Built in 1833-34 on land given by Arthur Daggett as a union meeting house for Congregationalist Unitarians and Methodists; the Methodists left about 1858. The builders, led by Truman and Stillman Kelton, included men who later worked on the Vermont State House. Services went to summer-only from 1940 to 1951 and have been year-round since.',
  'A brick Greek Revival church on a cut granite foundation, with a square tower and an eight-sided steeple. Inside are the original slip pews and the original pulpit, moved to the rear wall in the early 1900s.',
  '',
  'An active church, 55 VT Route 14 at US 2. Its page gives Sunday worship at 10 a.m.; visitors see the inside at services.',
  [W('East Village Meetinghouse'),['Old Brick Church','http://www.oldbrickchurch.com/']],brick='yes'),
# ---- Calais ----
N('kent-tavern-calais','Kent Tavern, Kents Corner','Calais','vtc','hotel','standing',44.36870,-72.48539,'site','view','drive','','1833–1837',
  'Abdiel Kent built this brick tavern between 1833 and 1837 at the crossroads his family had settled; it was a stagecoach stop on the Montpelier-to-Canada road from 1837 to 1846, and he and his brother Ira ran a store in its wooden wing until 1860. A. Atwater Kent, the radio maker, bought it in 1930 to restore as a museum; the Vermont Historical Society ran it as the Kent Tavern Museum from 1953 to 1988, and the state took it over in 1991.',
  'The Federal brick tavern, its wooden store wing and the barn across the road; the crossroads hamlet round it is a historic district with a 19th-century sawmill north of the junction. Inside, conservation work is half done: open plaster, lath and old wallpaper (Seven Days, 2026).',
  'A stagecoach tavern frozen in mid-repair, opened once a year for an art show.',
  'Kents Corner State Historic Site, owned by the state (Division for Historic Preservation) and not usually open; the annual Art at the Kent exhibition opens it in September and early October. On dirt roads at Kent Hill Road and Old West Church Road, which can be poor in winter and spring. See it from the road at other times.',
  [W('Kents Corner Historic District'),HM(168139,'Historic Kent Tavern'),['Seven Days: Art at the Kent faces an uncertain future','https://www.sevendaysvt.com/arts-culture/art-at-the-kent-in-calais-faces-an-uncertain-future/']],brick='yes'),
N('old-west-church-calais','Old West Church','Calais','vtc','worship','standing',44.35919,-72.4927,'site','view','drive','','1823–1825',
  'A rural meeting house built in 1823-25 in a style more usual in the late 1700s, little altered since. The pulpit was lowered from gallery height a few years after it was built, and wood stoves went in at the back in 1831; lightning damaged the steeple in 1953.',
  'A tall clapboarded church with three front doors and a three-stage tower. Inside, galleries on three sides on square posts, the pulpit on the far wall and the original plain pine box pews; no modern services, heat only from the 1831 stoves. Summer concerts are held in it (community calendar listings).',
  'Box pews and wood stoves, with no electricity.',
  'On Old West Church Road, 0.8 mile south of Kents Corner. Opening times not checked; see it from the road.',
  [W('Old West Church (Calais, Vermont)')],brick='no'),
# ---- Northfield and Roxbury ----
N('northfield-falls-covered-bridge','Northfield Falls and Lower Cox Brook covered bridges','Northfield','vtc','landmark','standing',44.1725,-72.65111,'exact','public','drive','','1872',
  'Two 1872 covered bridges on Cox Brook Road within sight of each other, which Wikipedia calls the only place in Vermont where that is so: the 137-foot Town lattice Northfield Falls (Station) bridge over the Dog River, and the 56-foot queen post Lower Cox Brook bridge just west. The Upper Cox Brook bridge is a little farther up the same road, and the Slaughter House bridge just south: five covered bridges survive in the town.',
  'Both bridges, one lane each, still carrying traffic; the Northfield Falls bridge has a centre pier added later.',
  'Two covered bridges you can see from one spot.',
  'Town roads in Northfield Falls, just west of VT Route 12. Drive or walk through; watch for traffic.',
  [W('Northfield Falls Covered Bridge'),W('Lower Cox Brook Covered Bridge'),W('Upper Cox Brook Covered Bridge')],brick='no'),
N('stony-brook-covered-bridge','Stony Brook Covered Bridge','Northfield','vtc','landmark','standing',44.12028,-72.68917,'exact','public','drive','','1899',
  'Built in 1899 and thought to be the last king post covered bridge built in Vermont in the historic period; it and the Pine Brook bridge in Waitsfield are the state\'s only two surviving historic king post bridges.',
  'A short (36-foot) single-span bridge on stone abutments faced in concrete, with a plank deck.',
  '',
  'Stony Brook Road, a town road in southern Northfield. One lane.',
  [W('Stony Brook Covered Bridge')],brick='no'),
N('old-red-mill-northfield','Old Red Mill','Northfield','vtc','industry','standing',44.11861,-72.6575,'site','view','drive','','1897–1898',
  'Mills stood here from at least the early 1800s. M. W. Partch built this one in 1897-98 after the last burned in 1896; it ground grain until the mid-1940s and added a cider mill in the 1930s.',
  'A wooden mill with vertical board siding on a slate foundation, with a cupola. The Register form (1977) describes a nearly complete water-powered milling works inside: concrete dam, penstock, metal turbine, line shaft, belts and grain-cleaning machines. Interior not checked; whether the machinery is still there was not confirmed.',
  '',
  'At VT Route 12 and Lovers Lane, South Northfield. Ownership not checked: see it from the road.',
  [W('Old Red Mill')],conf='mixed',brick='no'),
N('northfield-railway-depot','Central Vermont Railway Depot','Northfield','vtc','rail','standing',44.14861,-72.65833,'exact','view','drive','stations','1852',
  'Built in 1852 and believed to be the oldest railroad station left in Vermont, once the centre of a group of Central Vermont buildings. It closed in the 1970s; its side wings were pulled down after years of decay.',
  'A two-storey brick depot on a cut stone foundation with very deep (4-foot) bracketed eaves, at the end of Depot Square. Used as a bank branch (Wikipedia), so the inside is seen in business hours only; interior not checked.',
  '',
  'Depot Square, Northfield village. See it from the square.',
  [W('Northfield station (Vermont)')],brick='yes'),
N('roxbury-fish-hatchery','Roxbury Fish Culture Station','Roxbury','vtc','water','standing',44.06507,-72.744,'site','public','drive','','1891',
  'Vermont\'s oldest state fish hatchery, opened in 1891 on land given by E. H. Spaulding for its spring water and its railroad siding. Tropical Storm Irene wrecked its ponds in 2011; after a $6 million rebuild it reopened in 2020.',
  'The 1891 hatchery building, an 1890s fish-food house, an 1897 carriage barn and a 1930s CCC storage barn (the Register listing), and outdoor pools where the public may feed the fish.',
  '',
  'Vermont Fish and Wildlife Department, on VT Route 12A. The outdoor grounds are open to the public (VTDigger, 2020; Town of Roxbury). Hours not checked.',
  [W('Roxbury Fish Hatchery'),['Town of Roxbury: fish hatchery','https://roxburyvt.gov/roxbury-fish-hatchery/'],['VTDigger: hatchery back after Irene (2020)','https://vtdigger.org/2020/12/10/roxbury-hatchery-back-in-action-nine-years-after-irene-wrecked-it/'],HM(136544,'Roxbury Fish Culture Station')],brick='?'),
# ---- Mad River Valley ----
N('great-eddy-covered-bridge','Great Eddy Covered Bridge','Waitsfield','vtc','landmark','standing',44.18939,-72.8235,'exact','public','walk','','1833',
  'Built in 1833 over the Mad River, one of Vermont\'s two oldest covered bridges and its longest single-span Burr truss (105 feet). Repaired many times since; in Tropical Storm Irene in 2011 the river rose to its deck and it survived.',
  'The Burr arch truss bridge in the middle of the village, with a covered walkway along its east side.',
  '',
  'Bridge Street, Waitsfield village, a town road off VT Route 100. Use the walkway on foot.',
  [W('Great Eddy Covered Bridge')],brick='no'),
N('warren-covered-bridge','Warren Covered Bridge','Warren','vtc','landmark','standing',44.11111,-72.85694,'exact','public','drive','','1880s–1890',
  'A queen post covered bridge over the Mad River in Warren village, closed in 1999 when inspectors found hidden decay, rebuilt and reopened in October 2000; Irene damaged an abutment in 2011. Wikipedia files it under bridges completed in 1890 but its text gives no building date.',
  'One of only two Vermont bridges whose trusses are boarded inside as well as out; the east portal overhangs the road more than the west.',
  '',
  'Covered Bridge Road, Warren village, open to traffic.',
  [W('Warren Covered Bridge')],conf='mixed',brick='no'),
# ---- Camel's Hump ----
N('camels-hump-b24-wreck','B-24 bomber wreck, Camel\'s Hump','Duxbury','vtc','landmark','traces',44.31748,-72.87752,'area','public','hike','','1944',
  'A B-24J Liberator from Westover Field, Massachusetts, flew into Camel\'s Hump just below the summit at night in October 1944 on a training flight. Nine of the ten men aboard were killed; the gunner Jimmy Wilson survived two nights on the mountain before a search party of Civil Air Patrol cadets found him, and lost his hands and feet to frostbite.',
  'A 30- to 40-foot section of wing among the stunted spruce below the summit, and an engine beside a fallen tree (VTDigger, 2023). It is a very short spur off the yellow-blazed Alpine Trail.',
  'A bomber wing lying in the spruce below the summit.',
  'Camel\'s Hump State Park: free, no office or facilities. From the Monroe Trail lot at the end of Camel\'s Hump Road, Duxbury, the Green Mountain Club\'s loop runs about 8 miles up the Monroe and Alpine trails past the crash site. The lots fill on summer days and the road above the winter lot is not plowed. Dogs leashed above tree line; stay on bare rock in the alpine zone. A memorial site: leave every piece where it lies.',
  [['Green Mountain Club: Monroe and Alpine trails','https://greenmountainclub.org/?p=21274'],['VTDigger: the bomber crash on Camel\'s Hump (2023)','https://vtdigger.org/2023/01/22/then-again-years-of-research-reveal-details-of-bomber-crash-on-camels-hump/'],['Vermont State Parks: Camel\'s Hump','https://vtstateparks.com/camelshump.html']],
  th=[44.31625,-72.84949],thn='Monroe Trail lot, Camel\'s Hump Road',brick='no'),
]
